const items = $input.all();
const files = $('Read/Write Files from Disk').all();

const chunkSize = 2000;
const overlap = 200;

const chunks = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  const text =
    item.json.text ||
    item.json.content ||
    '';

  // Get the original PDF filename from Read Files from Disk
  const source =
    files[i]?.json?.fileName ||
    `document_${i + 1}.pdf`;

  if (!text.trim()) {
    continue;
  }

  let start = 0;

  while (start < text.length) {
    let end = Math.min(start + chunkSize, text.length);

    // Prefer ending at a newline
    if (end < text.length) {
      const newline = text.lastIndexOf('\n', end);

      if (newline > start + 500) {
        end = newline;
      }
    }

    const chunk = text.slice(start, end).trim();

    if (chunk.length > 200) {
      chunks.push({
        json: {
          content: chunk,
          metadata: {
            source: source
          }
        }
      });
    }

    if (end >= text.length) {
      break;
    }

    start = end - overlap;
  }
}

return chunks;

const text = query.dateRequest.toLowerCase().trim();

const now = new Date();

const weekdays = {
  monday: 1,
  tuesday: 2,
  wednesday: 3,
  thursday: 4,
  friday: 5,
  saturday: 6,
  sunday: 0,

  понеделник: 1,
  вторник: 2,
  сряда: 3,
  четвъртък: 4,
  петък: 5,
  събота: 6,
  неделя: 0
};

const months = {
  януари: 0,
  февруари: 1,
  март: 2,
  април: 3,
  май: 4,
  юни: 5,
  юли: 6,
  август: 7,
  септември: 8,
  октомври: 9,
  ноември: 10,
  декември: 11,

  january: 0,
  february: 1,
  march: 2,
  april: 3,
  may: 4,
  june: 5,
  july: 6,
  august: 7,
  september: 8,
  october: 9,
  november: 10,
  december: 11
};

// Get current date in Sofia timezone
function getSofiaDate() {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Sofia',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(now);

  const year = Number(
    parts.find(p => p.type === 'year').value
  );

  const month = Number(
    parts.find(p => p.type === 'month').value
  );

  const day = Number(
    parts.find(p => p.type === 'day').value
  );

  return new Date(year, month - 1, day);
}

function formatDate(date) {
  const year = date.getFullYear();

  const month = String(
    date.getMonth() + 1
  ).padStart(2, '0');

  const day = String(
    date.getDate()
  ).padStart(2, '0');

  return `${year}-${month}-${day}`;
}

const sofiaToday = getSofiaDate();

let target = new Date(sofiaToday);

// TODAY
if (
  text.includes('today') ||
  text.includes('днес')
) {
  target = new Date(sofiaToday);
}

// TOMORROW
else if (
  text.includes('tomorrow') ||
  text.includes('утре')
) {
  target = new Date(sofiaToday);
  target.setDate(target.getDate() + 1);
}

// OTHER DATE EXPRESSIONS
else {

  // Example:
  // 12.09.2026
  // 12/09/2026
  // 12-09-2026
  const numericMatch = text.match(
    /(\d{1,2})[./-](\d{1,2})(?:[./-](\d{4}))?/
  );

  if (numericMatch) {

    const day = Number(numericMatch[1]);

    const month =
      Number(numericMatch[2]) - 1;

    const year = numericMatch[3]
      ? Number(numericMatch[3])
      : sofiaToday.getFullYear();

    target = new Date(
      year,
      month,
      day
    );
  }

  else {

    let foundDate = false;

    // Example:
    // 12 септември
    // 12 september
    for (
      const [monthName, monthNumber]
      of Object.entries(months)
    ) {

      const regex = new RegExp(
        `(\\d{1,2})\\s*${monthName}`
      );

      const match = text.match(regex);

      if (match) {

        const day = Number(match[1]);

        let year =
          sofiaToday.getFullYear();

        const yearMatch =
          text.match(/\b(20\d{2})\b/);

        if (yearMatch) {
          year = Number(yearMatch[1]);
        }

        target = new Date(
          year,
          monthNumber,
          day
        );

        foundDate = true;

        break;
      }
    }

    // WEEKDAY
    if (!foundDate) {

      for (
        const [name, dayNumber]
        of Object.entries(weekdays)
      ) {

        if (text.includes(name)) {

          const currentDay =
            sofiaToday.getDay();

          let daysAhead =
            (dayNumber - currentDay + 7) % 7;

          // "next Monday"
          // "следващия понеделник"
          if (
            text.includes('next') ||
            text.includes('следващ')
          ) {

            if (daysAhead === 0) {
              daysAhead = 7;
            }
          }

          target = new Date(
            sofiaToday
          );

          target.setDate(
            target.getDate() + daysAhead
          );

          foundDate = true;

          break;
        }
      }
    }
  }
}

// Final result
const date = formatDate(target);

const weekday =
  target.toLocaleDateString('en-US', {
    weekday: 'long'
  }).toLowerCase();

// IMPORTANT:
// Code Tool expects ONE STRING as output.
return `date=${date}; weekday=${weekday}; startTime=${date}T09:00:00+03:00; endTime=${date}T17:00:00+03:00`;

